    var controls = spanLayer(comp.layers.addNull());
    controls.name = "MASTER_CONTROLS";
    addSlider(controls, "Progress", 0);
    addSlider(controls, "Line Weight", 100);
    addSlider(controls, "Grid Width", 100);
    addSlider(controls, "Title Opacity", 100);
    addSlider(controls, "Legend Opacity", 100);
    addSlider(controls, "Readout Opacity", 100);
    addSlider(controls, "Playhead Width", 100);
    addSlider(controls, "Dot Scale", 100);
    addSlider(controls, "Dot Opacity", 100);
    addSlider(controls, "Reveal Softness", 0);
    addSlider(controls, "Grid Opacity", 45);
    addSlider(controls, "Labels Opacity", 100);
    addSlider(controls, "Playhead Opacity", 35);
    addSlider(controls, "Tip Size", 16);
    addColor(controls, "Bandwidth_Mbps Color", [0.9500, 0.9500, 0.9500]);
